export async function cachedFetch(t,e=3e5){const a="cf_"+t;try{const t=sessionStorage.getItem(a);if(t){const{data:e,exp:s}=JSON.parse(t);if(Date.now()<=s)return e;sessionStorage.removeItem(a)}}catch{}const s=await fetch(t),n=await s.json();try{sessionStorage.setItem(a,JSON.stringify({data:n,exp:Date.now()+e}))}catch{}return n}export async function cachedHTML(t){const e="html_"+t;try{const t=sessionStorage.getItem(e);if(t){const{data:a,exp:s}=JSON.parse(t);if(Date.now()<=s)return a;sessionStorage.removeItem(e)}}catch{}const a=await fetch(t),s=await a.text();try{sessionStorage.setItem(e,JSON.stringify({data:s,exp:Date.now()+18e5}))}catch{}return s}